import {
    MSRPSession,
    MSRPSessionEventMap
} from '@/lib/msrp/session'
import { EndEvent,
    IncomingAckEvent,
    IncomingEvent,
    OutgoingAckEvent,
    OutgoingEvent,
    SessionDirection } from 'jssip/lib/RTCSession'

import { StreamMediaType } from '@/types/rtc'
import MSRPMessage from '@/lib/msrp/message'

export { MSRPMessage }

export type ListenerEventType = EndEvent | IncomingEvent | OutgoingEvent | IncomingAckEvent | OutgoingAckEvent

export interface IMessage extends MSRPSessionExtended {
    roomId?: number
    localMuted?: boolean
    localHold?: boolean
    audioTag?: StreamMediaType
    terminate(): void
}


export interface MSRPSessionExtended extends MSRPSession {
    id: string
    status: string
    start_time: Date
    direction: SessionDirection
    _id: string
    _cancel_reason: string
    _contact: string
    _end_time: Date
    _eventsCount: number
    _from_tag: string
    _is_canceled: boolean
    _is_confirmed: boolean
    _late_sdp: string
    _status: number
    _remote_identity: string
    _userTerminated?: boolean
    target_addr: Array<string>
    answer(options?: any): void
    _init_incomeing(): void
    sendMSRP(body: string): void
    on<T extends keyof MSRPSessionEventMap>(type: T, listener: MSRPSessionEventMap[T]): this;
}

export interface TriggerMSRPListenerOptions {
    listenerType: string
    session: MSRPSessionExtended
    event?:  ListenerEventType
}

/* ---------- MSRP conversation shape types (backend v3 - June 2026) ----------
 * These are the public data structures produced by MSRPModule at runtime and
 * consumed by external subscribers (Vue wrappers, tests, etc.). Kept in this
 * shipped `src/types/` file so they resolve cleanly for consumers without
 * needing internal module paths.
 */

export type MSRPMemberRole = 'in_charge' | 'manager' | 'assigned'
export type MSRPMembership = 'join' | 'leave' | 'invite' | 'ban'
export type MSRPMessageStatus = 'pending' | 'sent' | 'delivered' | 'read' | 'failed'

export interface MSRPTag {
    name: string
    color?: string
    added_by?: string
    added_at?: number
}

export interface MSRPConversationState {
    /**
     * Public, stable numeric conversation identifier assigned by the backend.
     * This is the only identifier exposed to application code — conversations
     * are addressed exclusively by `conversation_id`.
     */
    conversation_id?: number
    creator: string | null
    members: Set<string>
    memberRoles: Map<string, MSRPMemberRole>
    currentUserRole: MSRPMemberRole
    currentUserStatus: MSRPMembership | null
    /**
     * Per-user read pointer (backend `last_read_message_id` in the current
     * user's member state). `null` means the whole conversation is unread;
     * an event_id means everything after that event is unread. Consumers
     * derive the unread count from this pointer + the local timeline.
     */
    currentUserLastReadMessageId?: string | null
    state_events: { [key: string]: { [stateKey: string]: any } }
    created_at: number
    updated_at: number
    status?: string
    /**
     * Shared conversation tags from `m.sync` / `m.conversation.tag`.
     * Compared by normalized (lowercase, trimmed) `name`.
     */
    tags?: MSRPTag[]
}

export interface MSRPUploadResult {
    upload_url: string
    expires_in?: number
    mime_type: string
    request_id: string
    filename?: string
    preview_url?: string
    icon_url?: string
    transcription?: string
    media_type?: string
}

/* ---------- External MSRP signaling ----------
 * Lets an MSRP-only OpenSIPSJS instance (no SIP socket of its own) delegate
 * the SIP part of the MSRP session (INVITE/ACK/BYE) to another, fully
 * connected OpenSIPSJS instance, typically living in another context.
 */

/**
 * Data a fully connected instance exposes so another instance can open the
 * MSRP socket. Contains credentials — never log it.
 */
export interface MSRPConnectionData {
    /** Own SIP URI, e.g. `sip:user@domain` */
    uri: string
    authorizationUser: string
    /** Digest realm, known once the SIP UA has answered a challenge */
    realm: string | null
    /** Digest HA1 cached by the SIP UA after a challenge */
    ha1: string | null
    /** Plain SIP password, until the SIP UA replaces it with the HA1 after a challenge */
    password: string | null
}

export interface MSRPSignalingInviteRequest {
    target: string
    /** Local SDP offer (contains the `a=path` obtained from the MSRP relay) */
    sdp: string
    /** Generated by the MSRP side so the session id is known before the INVITE is sent */
    callId: string
    fromTag: string
    /** Digest realm learned by the MSRP side; used for the INVITE R-URI */
    realm?: string
}

export interface MSRPSignalingInviteResult {
    toTag: string
    /** Remote SDP answer (contains the remote `a=path`) */
    sdp: string
    sessionExpires?: number
    sessionExpiresRefresher?: 'uac' | 'uas'
}

/** SIP signaling used by an MSRP-only instance instead of its own SIP UA. */
export interface MSRPSignaling {
    invite (request: MSRPSignalingInviteRequest): Promise<MSRPSignalingInviteResult>
    bye (callId: string): Promise<void>
    /** Remote side ended the dialog (e.g. BYE from the server). Returns an unsubscribe function. */
    onDialogTerminated (callback: (callId: string, cause: string) => void): () => void
}
